const gvState={delegations:{},grants:{},preview:'正常',index:{},submitted:false,clarified:false,accepted:null,answers:{},choices:{},reasons:{},categories:{},settings:{},retrieval:null};
function gvEsc(gvValue){return String(gvValue==null?'':gvValue).replace(/[&<>"']/g,gvChar=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[gvChar]));}
function gvIcons(){if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.6}});}
function gvKv(gvRows){return `<dl class="kv">${gvRows.map(gvRow=>`<dt>${gvRow[0]}</dt><dd>${gvRow[1]}</dd>`).join('')}</dl>`;}
function gvTable(gvHeads,gvRows){return `<div class="table-wrap"><table><thead><tr>${gvHeads.map(gvCell=>`<th>${gvCell}</th>`).join('')}</tr></thead><tbody>${gvRows.map(gvRow=>`<tr>${gvRow.map(gvCell=>`<td>${gvCell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function gvField(gvLabel,gvControl,gvHint=''){return `<label class="stack small">${gvLabel}${gvControl}${gvHint?`<span class="muted xs">${gvHint}</span>`:''}</label>`;}
function gvInput(gvAttrs){return `<input style="width:100%;min-height:44px;box-sizing:border-box" ${gvAttrs}>`;}
function gvSelect(gvAttrs,gvOptions){return `<select style="width:100%;min-height:44px" ${gvAttrs}>${gvOptions}</select>`;}
function gvArea(gvAttrs,gvValue=''){return `<textarea style="width:100%;min-height:100px;box-sizing:border-box" ${gvAttrs}>${gvEsc(gvValue)}</textarea>`;}
function gvLink(gvRoute,gvText){return `<a href="#/${gvRoute}">${gvText}</a>`;}
function gvMissing(gvTitle){return head('详情',gvTitle,'该对象不存在或不在你可见的范围内。')+card('没有找到对象','<div class="empty">请返回列表选择已有对象。</div>');}
function gvPreview(gvMode){gvState.preview=gvMode;const gvTarget=document.getElementById('gv-source-body');if(gvTarget){gvTarget.innerHTML=gvSourceBody(gvTarget.dataset.source);gvIcons();}document.querySelectorAll('[data-gv-preview]').forEach(gvButton=>gvButton.classList.toggle('on',gvButton.dataset.gvPreview===gvMode));}
function gvDanger(gvKind,gvId){
 const gvGrant=gvKind==='grant';const gvModify=gvKind==='modify';const gvFreeze=gvKind==='freeze';
 const gvTitle=gvModify?'修改编制授权':gvFreeze?'冻结委托':gvGrant?'撤销编制授权':'撤销委托';
 const gvConsequence=gvModify?'增加在岗名额至 4；其余范围与预算保持原授权条件。':gvGrant?'撤销立即生效。主管不能继续创建；未收编的子 Agent 停机并成为孤儿，等待你收编，不会被退役。已收编的 Fern 不受影响。':gvFreeze?'冻结后，Agent 暂时不能经此委托裁决；历史裁决保持可追溯。':'撤销立即生效，进行中的裁决在提交时不能再借用此委托；已发生的裁决保留。';
 openModal(`<div class="stack" style="padding:24px"><h3>${gvTitle} · ${gvEsc(gvId)}</h3><div class="note danger">${I('triangle-alert')}${gvConsequence}</div>${gvField('理由（必填）',gvArea('id="gv-danger-reason" maxlength="2000" oninput="gvDangerValidate()"'),'至少 10 字，最多 2000 字。')}<div class="note warn">${I('lock-keyhole')}需重新认证 · 证明绑定本次动作与对象，5 分钟内一次有效。原型仅模拟确认，不执行真实认证。</div><label class="row"><input id="gv-danger-auth" type="checkbox" onchange="gvDangerValidate()">模拟已完成本次重新认证</label><div class="row wrap"><button class="btn" onclick="closeModal()">取消</button><button class="btn danger" id="gv-danger-confirm" disabled onclick="gvDangerCommit('${gvKind}','${gvId}')">确认${gvTitle}</button></div><span class="muted xs" id="gv-danger-hint">填写理由并完成模拟认证后可确认。</span></div>`);
}
function gvDangerValidate(){document.getElementById('gv-danger-confirm').disabled=document.getElementById('gv-danger-reason').value.trim().length<10||!document.getElementById('gv-danger-auth').checked;}
function gvDangerCommit(gvKind,gvId){if(document.getElementById('gv-danger-confirm').disabled)return;const gvReason=document.getElementById('gv-danger-reason').value.trim();if(gvKind==='grant')gvState.grants[gvId]={state:'已撤销',reason:gvReason};else if(gvKind==='modify')gvState.grants[gvId]={state:'有效',slots:4,reason:gvReason};else gvState.delegations[gvId]={state:gvKind==='freeze'?'已冻结':'已撤销',reason:gvReason};closeModal();route();toast('已更新本页模拟状态；未写入真实授权与审计');}

