PAGES['ksource']=(gvArg)=>{
 const gvId=gvArg||'KS-0.82';const gvSource=gvSources[gvId];if(!gvSource)return gvMissing('知识源详情');const gvIndex=gvState.index[gvId]||'已索引';
 return head('知识库 / 来源',gvSource.title,'知识保留出处与内容指纹，引用不等于事实。',`<button class="btn" onclick="go('knowledge')">返回知识库</button>`)+`<div class="grid g12"><div class="c4 stack">${card('来源与出处',gvKv([['编号',gvId],['来源类型',gvSource.type],['出处',gvLink(gvSource.route,gvSource.origin)],['范围',gvSource.scope],['索引状态',S(gvIndex==='索引中'?'RUNNING':'PASSED',gvIndex)],['块数',gvSource.content.length],['索引时间','原型时间 · 今天 08:10']]))}${card('检索与引用',gvKv([['被检索','28 次'],['被引用','9 次'],['被接受的引用','7 次'],['最近引用',gvLink('workitem/BIL-142','BIL-142')]])+'<div class="muted xs">记忆仅影响 Agent 倾向，不代表事实；规则须由非写入者的人类批准。</div>')}${card('索引维护',`<button class="btn" ${gvIndex==='索引中'||gvState.preview==='无权限'?'disabled':''} onclick="gvReindex('${gvId}')">重新索引</button><div class="muted xs">仅已索引或失败且持 knowledge_write 时可用；索引中不可重复提交。</div><div class="note info">PostgreSQL · 全文检索 K1。混合 K2 模块未启用；需向量扩展与模型配置。</div>`)}</div><div class="c8 stack">${card('状态预览',`<div class="row wrap">${['正常','空','错误','无权限'].map(gvMode=>`<button class="chip ${gvState.preview===gvMode?'on':''}" data-gv-preview="${gvMode}" style="min-height:44px" onclick="gvPreview('${gvMode}');gvSourcePermission()">${gvMode}</button>`).join('')}</div>`)}<div id="gv-source-body" data-source="${gvId}">${gvSourceBody(gvId)}</div></div></div>`;
};
function gvSourcePermission(){const gvButton=document.querySelector('[onclick^="gvReindex"]');if(gvButton)gvButton.disabled=gvState.preview==='无权限'||gvState.index[document.getElementById('gv-source-body').dataset.source]==='索引中';}

function gvDebugRun(){
 const gvQuery=document.getElementById('gv-query').value.trim();const gvHint=document.getElementById('gv-query-hint');if(!gvQuery||gvQuery.length>500||!(/[\u3400-\u9fff]/.test(gvQuery)||/[a-z]{2}/i.test(gvQuery))){gvHint.textContent='请输入至少一个汉字或两个字母，查询长度 1–500 字。';return;}
 const gvScope=document.getElementById('gv-scope').value;const gvMode=document.getElementById('gv-mode').value;const gvActor=document.getElementById('gv-actor').value;const gvTop=Number(document.getElementById('gv-top').value);if(!Number.isInteger(gvTop)||gvTop<1||gvTop>200){gvHint.textContent='候选上限必须是 1–200 的整数。';return;}const gvWords=gvQuery.split(/\s+/);const gvIds=Object.keys(gvSources).filter(gvKey=>gvScope==='all'||gvSources[gvKey].scope.includes(gvScope));
 const gvResults=gvIds.map(gvKey=>{const gvSource=gvSources[gvKey];const gvText=gvSource.title+' '+gvSource.content.join(' ');const gvHits=gvWords.filter(gvWord=>gvText.toLowerCase().includes(gvWord.toLowerCase())).length;return {id:gvKey,T:gvHits/gvWords.length,R:.85,W:gvSource.type==='反馈'?1:.85,S:gvScope==='all'?.6:1,match:gvMode==='ALL'?gvHits===gvWords.length:gvHits>0};}).filter(gvRow=>gvRow.match).map(gvRow=>({...gvRow,final:.55*gvRow.T+.15*gvRow.R+.15*gvRow.W+.15*gvRow.S})).sort((gvA,gvB)=>gvB.final-gvA.final).slice(0,gvTop);
 gvState.retrieval={query:gvQuery,scope:gvScope,mode:gvMode,actor:gvActor,purpose:'DEBUG',engine:'K1',results:gvResults};gvHint.textContent='只读模拟可见集；不写 last_used_at。每次运行记录本页 DEBUG 日志。';document.getElementById('gv-debug-results').innerHTML=gvDebugResults();gvIcons();
}
function gvDebugResults(){const gvLog=gvState.retrieval;if(!gvLog)return '<div class="empty">输入查询并运行，查看候选结果与得分。</div>';return `<div class="stack"><div class="row wrap"><span class="badge b-info">PostgreSQL · K1 全文</span><span class="badge b-stale">K2 混合未启用</span><span class="badge">DEBUG · ${gvEsc(gvLog.actor)}</span></div><div class="row wrap">${gvLog.query.split(/\s+/).map(gvWord=>`<span class="chip">${gvEsc(gvWord)}${gvWord.length===1?' · 前缀':''}</span>`).join('')}</div><pre class="code" style="white-space:pre-wrap">${gvEsc('websearch_to_tsquery(查询参数) · '+gvLog.mode)}</pre><div class="muted xs">模拟耗时：分词 1 ms / SQL 候选 4 ms / 向量未启用 / 排序 1 ms</div>${gvLog.results.length?gvTable(['排名 / 来源','原始文本','T 文本','R 时间','W 来源','S 范围','文本排名 / 向量排名','最终'],gvLog.results.map((gvRow,gvIndex)=>[`${gvIndex+1} · ${gvLink('ksource/'+gvRow.id,gvSources[gvRow.id].title)}`,gvEsc(gvSources[gvRow.id].content[0]),gvRow.T.toFixed(2),gvRow.R.toFixed(2),gvRow.W.toFixed(2),gvRow.S.toFixed(2),`${gvIndex+1} / 未启用`,`<span title="0.55×${gvRow.T}+0.15×${gvRow.R}+0.15×${gvRow.W}+0.15×${gvRow.S}">${gvRow.final.toFixed(3)}</span>`])):'<div class="empty">没有找到匹配内容。切换为任一词或放宽范围。</div>'}<div class="muted xs">低于阈值 0.20 的候选：0 条。得分为浏览器示例计算，非实际全文或向量排名。</div></div>`;}
function gvDebugExport(){if(!gvState.retrieval){toast('请先运行查询');return;}const gvUrl=URL.createObjectURL(new Blob([JSON.stringify(gvState.retrieval,null,2)],{type:'application/json'}));const gvAnchor=document.createElement('a');gvAnchor.href=gvUrl;gvAnchor.download='retrieval-debug.json';gvAnchor.click();setTimeout(()=>URL.revokeObjectURL(gvUrl),1000);}
PAGES['retrieval-debug']=()=>head('知识库 / 管理','检索调试','你以 knowledge_manage 权限演示查询；范围只影响候选，不改变来源内容。',`<button class="btn" onclick="go('knowledge')">返回知识库</button><button class="btn" onclick="gvDebugExport()">导出 JSON</button>`)+`<div class="grid g12"><div class="c4 stack">${card('查询与可见集',`<div class="stack">${gvField('查询',gvInput('id="gv-query" maxlength="500" value="导出 金额"'))}${gvField('匹配方式',gvSelect('id="gv-mode"','<option value="ALL">全部词</option><option value="ANY">任一词</option>'))}${gvField('范围',gvSelect('id="gv-scope"','<option value="账单中心">账单中心</option><option value="all">团队与可见项目</option><option value="商户控制台">商户控制台</option>'))}${gvField('以谁的视角',gvSelect('id="gv-actor"','<option value="morgan">你 · Morgan</option><option value="ada">Ada · 账单中心</option><option value="bo">Bo · 账单中心</option>'))}${gvField('候选上限',gvInput('id="gv-top" type="number" min="1" max="200" value="10"'))}<button class="btn primary" onclick="gvDebugRun()">运行检索</button><span id="gv-query-hint" class="muted xs" role="status">范围限定为你可见的项目；无 knowledge_manage 时不可进入。</span></div>`) }${card('评分与后端',`<div class="code">0.55T+0.15R+0.15W+0.15S</div>${gvKv([['T','文本相关度'],['R','时间衰减'],['W','来源权重'],['S','范围加成'],['后端','PostgreSQL · K1 全文'],['K2','混合检索未启用，当前无向量排名']])}`)}</div><div class="c8">${card('候选结果与得分分解','<div id="gv-debug-results">'+gvDebugResults()+'</div>')}</div></div>`;

function gvSettingsSave(){const gvForm=document.getElementById('gv-settings-form');if(!gvForm.reportValidity())return;gvState.settings=Object.fromEntries(new FormData(gvForm));gvForm.querySelectorAll('input[type=checkbox]:not(:disabled)').forEach(gvControl=>{gvState.settings[gvControl.name]=gvControl.checked?'on':'off';});toast('个人资料、偏好与通知已保存到本页模拟状态');}
function gvNotificationsReset(){document.querySelectorAll('[data-gv-notification]').forEach(gvInputEl=>{if(gvInputEl.tagName==='SELECT')gvInputEl.value='即时';else gvInputEl.checked=true;});toast('通知已恢复默认，保存后生效');}
function gvBrowserNotify(){if(!('Notification' in window)){toast('浏览器不支持通知，请使用站内通知');return;}Notification.requestPermission().then(gvPermission=>{document.getElementById('gv-push-status').textContent=gvPermission==='granted'?'浏览器已授权；真实推送订阅需通知服务':gvPermission==='denied'?'已拒绝，请在浏览器站点设置中允许通知':'未授权';});}
PAGES['settings']=()=>{setTimeout(gvSettingsRestore,0);return head('个人空间','个人设置','资料、偏好与通知仅影响你；安全由底座身份服务管理。')+`<form id="gv-settings-form" onsubmit="event.preventDefault();gvSettingsSave()"><div class="grid g12"><div class="c6 stack">${card('资料',`<div class="stack"><div class="row">${A('morgan','lg')}<span>Morgan · 交付负责人</span></div>${gvField('昵称',gvInput(`name="nickname" required maxlength="100" value="${gvEsc(gvState.settings.nickname||'Morgan')}"`))}${gvField('邮箱',gvInput(`name="email" type="email" required value="${gvEsc(gvState.settings.email||'morgan@northwind.example')}"`))}<div class="muted xs">头像沿用你当前账号的身份资料。</div></div>`)}${card('偏好',`<div class="stack">${gvField('主题',gvSelect('name="theme"','<option>跟随系统</option><option>浅色</option><option>深色</option>'))}${gvField('语言',gvSelect('name="language"','<option>简体中文</option><option>英语</option><option>马来语</option>'))}<div class="muted xs">此处保存偏好示例；原型全局主题仍由顶栏管理。</div></div>`)}${card('安全',`<div class="stack"><a class="btn" href="javascript:void 0" onclick="toast('将在底座 IAM 应用中打开：账号安全 › 多因素认证','external-link')">${I('shield-check')}到底座管理多因素认证</a><a class="btn" href="javascript:void 0" onclick="toast('将在底座 IAM 应用中打开：账号安全 › 登录会话','external-link')">${I('key-round')}到底座查看登录会话</a><div class="note info">底座页面不在本产品原型中；不会在这里修改认证因子或吊销真实会话。</div></div>`)}</div><div class="c6 stack">${card('免打扰与浏览器通知',`<div class="stack"><label class="row"><input name="dnd" type="checkbox" checked>启用免打扰</label><div class="grid g12"><div class="c6">${gvField('开始',gvInput('name="dnd_start" type="time" value="22:00"'))}</div><div class="c6">${gvField('结束',gvInput('name="dnd_end" type="time" value="08:00"'))}</div></div>${gvField('时区',gvInput('name="timezone" value="'+gvEsc(Intl.DateTimeFormat().resolvedOptions().timeZone)+'"'))}${gvField('每日摘要',gvInput('name="digest" type="time" value="09:00"'))}<label class="row"><input name="mentions_only" type="checkbox">只看 @我（不影响强制与紧急通知）</label><span class="muted xs" id="gv-push-status">浏览器通知未授权</span><button type="button" class="btn" onclick="gvBrowserNotify()">启用浏览器通知</button><div class="note warn">紧急通知绕过免打扰；站内通知永不抑制。浏览器被拒绝时，请在站点设置中开启。</div></div>`)}${card('通知类型与渠道',gvTable(['类型 / 示例','站内','浏览器','邮件'],[['裁决待办','BIL-142 待你裁决',true,false],['创建审批','Atlas 创建请求待确认',true,false],['升级告警','商户控制台预算升级',true,true],['澄清回复','甲方已回答权限问题',false,false],['执行关注','验证需要人工确认',true,false],['规则待审','规则记忆待你审批',true,false],['@你','频道中有人提及你',false,false]].map((gvRow,gvIndex)=>[`${gvRow[0]}<div class="muted xs">${gvRow[1]} · ${gvRow[3]?'紧急':'普通'}</div>`,`<label><input data-gv-notification name="notice_${gvIndex}" type="checkbox" checked ${gvRow[2]?'disabled':''} aria-label="${gvRow[0]}站内">${gvRow[2]?I('lock')+' 强制':''}</label>`,`<input data-gv-notification name="push_${gvIndex}" type="checkbox" checked aria-label="${gvRow[0]}浏览器">`,gvSelect(`data-gv-notification name="mail_${gvIndex}" aria-label="${gvRow[0]}邮件" ${gvRow[3]?'disabled':''}`,'<option>即时</option><option>每日摘要</option><option>关闭</option>')]))+`<button class="btn" type="button" onclick="gvNotificationsReset()">恢复默认</button><div class="muted xs">锁定项不能关闭。真实保存使用版本校验；冲突时提示「设置已在其他设备更改」并重载。</div>`)}<button class="btn primary" type="submit">保存设置</button></div></div></form>`;};

function gvSettingsRestore(){const gvForm=document.getElementById('gv-settings-form');if(!gvForm)return;for(const [gvName,gvValue] of Object.entries(gvState.settings)){const gvControl=gvForm.elements.namedItem(gvName);if(gvControl){if(gvControl.type==='checkbox')gvControl.checked=gvValue==='on';else gvControl.value=gvValue;}}}

[['delegation','委托详情','policy'],['spawn-grant','编制授权详情','policy'],['audit-event','审计事件详情','audit'],['ksource','知识源详情','knowledge'],['retrieval-debug','检索调试','knowledge'],['settings','个人设置','overview']].forEach(gvEntry=>{TITLES[gvEntry[0]]=gvEntry[1];NAVPARENT[gvEntry[0]]=gvEntry[2];});
